<template><section class="page"><header><div><h2>维修人员管理</h2><p>维护维修技能、值班状态和自动派单负载上限。</p></div><el-button type="primary" @click="open()">新增维修人员</el-button></header><el-table :data="rows" border><el-table-column prop="employeeCode" label="工号" width="130"/><el-table-column prop="technicianName" label="姓名" width="120"/><el-table-column prop="phone" label="电话" width="140"/><el-table-column prop="skillCategories" label="技能分类" min-width="200"/><el-table-column label="负载" width="100"><template #default="{row}">{{row.currentLoad}} / {{row.maxConcurrent}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}">{{workLabels[row.workStatus]}}</template></el-table-column><el-table-column label="自动派单" width="100"><template #default="{row}">{{row.autoDispatch?'是':'否'}}</template></el-table-column><AdaptiveActionColumn label="操作" :width="90"><template #default="{row}"><el-button link @click="open(row)">编辑</el-button></template></AdaptiveActionColumn></el-table><el-dialog v-model="dialog" :title="form.id?'编辑维修人员':'新增维修人员'" width="600px"><el-form label-width="110px"><el-form-item label="员工"><el-select v-model="form.employeeId" filterable :disabled="!!form.id" style="width:100%"><el-option v-for="item in employees" :key="item.id" :value="item.id" :label="`${item.employeeName}（${item.employeeCode}）`"/></el-select></el-form-item><el-form-item label="技能分类"><el-select v-model="skills" multiple style="width:100%"><el-option v-for="(label,value) in categoryLabels" :key="value" :value="value" :label="label"/><el-option value="ALL" label="全类别"/></el-select></el-form-item><el-form-item label="工作状态"><el-select v-model="form.workStatus" style="width:100%"><el-option v-for="(label,value) in workLabels" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item label="最大并发工单"><el-input-number v-model="form.maxConcurrent" :min="1" :max="100"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.active"/></el-form-item><el-form-item label="参与自动派单"><el-switch v-model="form.autoDispatch"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></section></template>
<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage } from 'element-plus';import { employees as loadEmployees } from '../../iam/api';import { createTechnician, technicians, updateTechnician } from '../api';import { categoryLabels } from '../labels'
const rows=ref([]),employees=ref([]),dialog=ref(false),skills=ref([]);const workLabels={AVAILABLE:'可接单',BUSY:'忙碌',OFFLINE:'离线'};const form=reactive({id:'',employeeId:'',workStatus:'AVAILABLE',maxConcurrent:5,active:true,autoDispatch:true})
const load=async()=>{rows.value=(await technicians()).data||[]};const open=row=>{Object.assign(form,row||{id:'',employeeId:'',workStatus:'AVAILABLE',maxConcurrent:5,active:true,autoDispatch:true});skills.value=(row?.skillCategories||'').split(',').filter(Boolean);dialog.value=true}
const save=async()=>{if(!form.employeeId||!skills.value.length)return ElMessage.warning('请选择员工和技能分类');const body={...form,skillCategories:skills.value.join(',')};form.id?await updateTechnician(form.id,body):await createTechnician(body);ElMessage.success('保存成功');dialog.value=false;load()}
onMounted(async()=>{const r=await loadEmployees({page:0,size:100});employees.value=r.data?.content||r.data||[];await load()})
</script><style scoped>.page{padding:24px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}h2{margin:0 0 6px}p{margin:0;color:#84909a}</style>
